rt. 20."},{"id":8614,"materia":"prev","nivel":0,"enunciado":"O valor do BPC é de:","opcoes":["Um salário mínimo","Meio salário mínimo","Dois salários mínimos","Variável conforme a contribuição"],"explicacao":"CF, art. 203, V."},{"id":8615,"materia":"prev","nivel":0,"enunciado":"O BPC exige contribuição prévia ao INSS?","opcoes":["Não","Sim, 15 anos","Sim, 12 meses","Sim, 5 anos"],"explicacao":"É benefício assistencial."},{"id":8616,"materia":"prev","nivel":0,"enunciado":"O segurado empregado, o doméstico e o avulso são segurados:","opcoes":["Obrigatórios","Facultativos","Dependentes","Especiais apenas"],"explicacao":"Lei 8.213/1991, art. 11."},{"id":8617,"materia":"prev","nivel":0,"enunciado":"A dona de casa sem renda própria que contribui para o INSS é segurada:","opcoes":["Facultativa","Obrigatória","Especial","Avulsa"],"explicacao":"Lei 8.213/1991, art. 13."},{"id":8618,"materia":"prev","nivel":0,"enunciado":"O pescador artesanal e o pequeno produtor rural em regime de economia familiar são segurados:","opcoes":["Especiais","Facultativos","Avulsos","Domésticos"],"explicacao":"Lei 8.213/1991, art. 11, VII."},{"id":8619,"materia":"prev","nivel":0,"enunciado":"O benefício pago aos dependentes do segurado que morre é a:","opcoes":["Pensão por morte","Aposentadoria por idade","Auxílio-doença","Salário-família"],"explicacao":"Lei 8.213/1991, art. 74."},{"id":8620,"materia":"prev","nivel":0,"enunciado":"O benefício pago ao segurado temporariamente incapaz para o trabalho por mais de 15 dias é o:","opcoes":["Auxílio por incapacidade temporária","BPC","Pensão por morte","Salário-família"],"explicacao":"Antigo auxílio-doença."},{"id":8621,"materia":"prev","nivel":0,"enunciado":"Os primeiros 15 dias de afastamento do segurado empregado por doença são pagos:","opcoes":["Pela empresa","Pelo INSS","Pelo SUS","Pelo sindicato"],"explicacao":"Lei 8.213/1991, art. 60, § 3º."},{"id":8622,"materia":"prev","nivel":1,"enunciado":"A idade mínima para o trabalho, salvo como aprendiz, é 